import sys
import string

with open('/home/ctfplayer/ctf_files/stage-2.bin','rb') as f:
    data = f.read()

min_len = 4
results = []
tmp = b''
for b in data:
    if chr(b) in string.printable and chr(b) != '\x00':
        tmp += bytes([b])
    else:
        if len(tmp) >= min_len:
            results.append(tmp.decode('latin-1'))
        tmp = b''
if len(tmp) >= min_len:
    results.append(tmp.decode('latin-1'))

for s in results:
    print(s)
